//! 🧪️ The actual planner retains every original ordinal, input and page backing until exact retirement.
use super::super::{HistoryReadPlan,ReplayProgress,EffectiveSupersessions};
use ::protocol::{MutationId,InputReplacement,HybridLogicalTimestamp};
use semio_framework_trace::observe_heap_allocations_on_this_thread;
use semio_framework_value::{retirement::controlled::ControlledRetirement,retained_clone::{RetainedCloneGrant,RetainedCloneProgress},ValueRefusalKind};
fn text(value:&str,capacity:usize)->String {let mut result=String::with_capacity(capacity);result.push_str(value);result}
fn input(row:&serde_json::Value,law:&serde_json::Value)->InputReplacement {let mut payload=Vec::with_capacity(law["payloadCapacity"].as_u64().unwrap()as usize);for byte in row["payload"].as_array().unwrap(){payload.push(byte.as_u64().unwrap()as u8);}InputReplacement::Input {schema:text(row["schema"].as_str().unwrap(),law["textCapacity"].as_u64().unwrap()as usize),payload}}
fn make(law:&serde_json::Value,frontier:usize)->HistoryReadPlan {
    let drafts=law["drafts"].as_array().unwrap().iter().map(|row|(MutationId(text(row["id"].as_str().unwrap(),law["textCapacity"].as_u64().unwrap()as usize)),input(row,law))).collect();
    let mut plan=HistoryReadPlan::new(Some(MutationId(text(law["target"].as_str().unwrap(),law["textCapacity"].as_u64().unwrap()as usize))),drafts,17,true);
    for row in law["positions"].as_array().unwrap(){plan.positions.insert(MutationId(text(row["id"].as_str().unwrap(),337)),(row["edit"].as_u64().unwrap()as usize,row["operation"].as_u64().unwrap()as usize));}
    for row in law["order"].as_array().unwrap().iter().take(frontier){plan.order.push(text(row.as_str().unwrap(),337));}
    for value in law["counts"].as_array().unwrap().iter().take(frontier){plan.counts.push(value.as_u64().unwrap()as u32);}
    plan.located_draft=Some(MutationId(text("",337)));plan.copied=Some(MutationId(text("β",337)));plan.progress=ReplayProgress {done:7,total:17};
    let mut effective=EffectiveSupersessions::new();for row in law["drafts"].as_array().unwrap().iter().take(2){effective.insert(MutationId(text(row["id"].as_str().unwrap(),337)),protocol::EffectiveSupersession {transition_id:text("",337),actor:text("actor/🐚",337),timestamp:HybridLogicalTimestamp::new(7,11),scope:Some(text("",337)),replacement:input(row,law)});}plan.supersessions=effective;plan
}
#[test]
fn history_plan_retirement_owns_original_positions_inputs_and_empty_page_scaffolds() {
    let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();
    let(empty,heap)=observe_heap_allocations_on_this_thread(||HistoryReadPlan::new(None,protocol::HistoryInputDrafts::new(),17,true));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let(_,heap)=observe_heap_allocations_on_this_thread(||drop(empty));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
    for copy in law["copyGrants"].as_array().unwrap(){for frontier in law["cancelAt"].as_array().unwrap(){
        let(plan,heap)=observe_heap_allocations_on_this_thread(||make(&law,frontier.as_u64().unwrap()as usize));let held=heap.requested_bytes-heap.released_bytes;
        let actual=plan.positions.iter().map(|(id,(edit,operation))|serde_json::json!({"id":id.0,"edit":edit,"operation":operation})).collect::<Vec<_>>();assert_eq!(actual,law["expectedPositions"].as_array().unwrap().clone());
        let pointer=plan.target.as_ref().unwrap().0.as_ptr();let(target,heap)=observe_heap_allocations_on_this_thread(||ControlledRetirement::new(plan).unwrap_or_else(|_|panic!("planner controlled authority")));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(target.original().unwrap().target.as_ref().unwrap().0.as_ptr(),pointer);let mut target=target;let(mut allocated,mut released)=(0,0);
        for turn in 0..100000 {
            let copy=copy.as_u64().unwrap()as usize;let((work,capacity,release,depth),heap)=observe_heap_allocations_on_this_thread(||(target.next_copy_byte_demand().unwrap(),target.next_capacity_byte_demand(copy).unwrap(),target.next_release_byte_demand().unwrap(),target.next_depth_demand().unwrap()));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
            let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:copy.max(work),maximum_capacity_bytes:capacity,maximum_release_bytes:release,maximum_depth:depth};
            for below in [RetainedCloneGrant {maximum_items:0,..grant},RetainedCloneGrant {maximum_copy_bytes:work.saturating_sub(1),..grant},RetainedCloneGrant {maximum_capacity_bytes:capacity.saturating_sub(1),..grant},RetainedCloneGrant {maximum_release_bytes:release.saturating_sub(1),..grant},RetainedCloneGrant {maximum_depth:depth.saturating_sub(1),..grant}] {if below.maximum_items!=0&&below.maximum_copy_bytes>=work&&below.maximum_capacity_bytes>=capacity&&below.maximum_release_bytes>=release&&below.maximum_depth>=depth {continue;}let(step,heap)=observe_heap_allocations_on_this_thread(||target.step(below));match step {Ok(step)=>assert_eq!(step.progress(),RetainedCloneProgress::default()),Err(error)=>assert!(matches!(error.kind,ValueRefusalKind::DepthLimit|ValueRefusalKind::OwnershipLimit|ValueRefusalKind::WorkLimit))}assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}
            let(step,heap)=observe_heap_allocations_on_this_thread(||target.step(grant).unwrap());assert_eq!(step.progress().retained_capacity_bytes,heap.requested_bytes,"birth turn{turn}");assert_eq!(step.progress().released_bytes,heap.released_bytes,"release turn{turn}");assert!(step.progress().fits(grant));allocated+=heap.requested_bytes;released+=heap.released_bytes;
            if target.terminal_is_empty(){break;}assert!(turn<99999);
        }
        assert_eq!(released,held+allocated);let(_,heap)=observe_heap_allocations_on_this_thread(||drop(target));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
    }}
    println!("[DEBUG] native actual HistoryReadPlan original ordinal/draft/supersession/text/page owners preserved; empty constructor pages0heap; five-axis undergrants0effects; exact physical receipts; terminal Drop0heap");
}
